            <p class="text-sm">No chats found</p>
          </div>
        </div>

        <!-- Pagination info -->
        <div v-if="searchResultsData" class="sticky bottom-0 text-xs text-base-content/50 text-center py-2 bg-base-100 border-t border-base-300">
          {{ searchResultsData.results?.length || 0 }} / {{ searchResultsData.total || 0 }} results
        </div>
      </div>
    </template>

