            :key="chat.id"
            :chat="chat"
            :isActive="isActive(chat)"
            :chatProject="getChatProject(chat)"
            :badgeColor="badgeColor"
            :snippet="getLastMessageSnippet(chat)"
            @select="selectChat(chat)"
          />
        </div>
      </div>
    </template>
  </div>
</template>

<script>
export default {
  components: {
    ChatSearch,
    ChatCard
  },
  props: {
    collapsed: {
      type: Boolean,
      default: false
    }
  },
  data() {
    return {
      limit: 10,
      badgeColor: {
        task: 'primary',
        chat: 'accent'
      },
      isSearching: false,
      searchResultsData: null,
      selectedUserId: null,
      showUserFilterDropdown: false
    }
  },
  computed: {
    currentUser() {
      return this.$storex?.users?.user || this.$user
    },
    allUsers() {
      const users = this.$storex?.users?.allUsers || []
      return users.filter(u => u?.id || u?.userName)
    },
    otherUsers() {
      return this.allUsers.filter(u => u?.id !== this.currentUser?.id)
    },
    hasUserFilter() {
      return this.selectedUserId !== null && this.selectedUserId !== undefined
    },
    selectedUserName() {
      if (!this.hasUserFilter) return null
      const user = this.allUsers.find(u => u?.id === this.selectedUserId)
      return user?.userName || 'Unknown'
    },
    userFilterLabel() {
      if (this.hasUserFilter) {
        return `Chats by ${this.selectedUserName}`
      }
      return 'Recent Chats & Tasks'
    },
    noChatsMessage() {
      if (this.hasUserFilter) {
        return `No chats from ${this.selectedUserName}`
      }
      return 'No recent chats'
    },
    allChats() {
      return this.$storex?.chats?.allChats || []
    },
    sortedChats() {
      let chats = [...this.allChats]

      // Filter by project if no user filter is active
      if (!this.hasUserFilter) {
        const activeProjectId = this.$storex?.projects?.activeProject?.project_id
        chats = chats.filter(chat => 
          chat && chat.id && (chat.project_id === activeProjectId || chat.owner_project_id === activeProjectId)
        )
      } else {
        // Filter by selected user across all projects
        chats = chats.filter(chat => this.chatInvolvesUser(chat, this.selectedUserId))
      }

      // Sort by recency
      return chats.sort((a, b) => {
        const getChatTime = (c) => {
          if (c.updated_at) return new Date(c.updated_at).getTime()
          if (c.messages && c.messages.length > 0) {
            const lastMsg = c.messages[c.messages.length - 1]
            const t = lastMsg.updated_at || lastMsg.created_at
            if (t) return new Date(t).getTime()
          }
          return 0
        }
        return getChatTime(b) - getChatTime(a)
      })
    },
    recentChats() {
      return this.sortedChats.slice(0, this.limit)
    }
  },
  methods: {
    handleScroll(e) {
      const { scrollTop, clientHeight, scrollHeight } = e.target
      if (scrollHeight - scrollTop - clientHeight < 40) {
        if (this.limit < this.sortedChats.length) {
          this.limit += 10
        }
      }
    },
    getInitials(name) {
      if (!name) return 'CH'
      const cleanName = name.replace(/[^\w\s-]/g, '').trim()
      const words = cleanName.split(/\s+/)
      if (words.length >= 2) {
        return (words[0][0] + words[1][0]).toUpperCase()
      }
      return name.substring(0, 2).toUpperCase()
    },
    isActive(chat) {
      return this.$storex?.chats?.activeChat?.id === chat.id
    },
    async selectChat(chat) {
      await this.$storex.chats.setActiveChat(chat)
    },
    getChatProject(chat) {
      const projects = this.$storex?.projects?.allProjects || this.$projects?.allProjects || []
      return projects.find(p => p.project_id === chat.project_id || p.project_id === chat.owner_project_id) || this.$project
    },
    getLastMessageSnippet(chat) {
      if (!chat.messages || chat.messages.length === 0) {
        return 'No messages'
      }
      const messagesWithContent = [...chat.messages]
        .reverse()
        .filter(m => m.content || m.think)
      if (messagesWithContent.length === 0) {
        return 'No message content'
      }
      const lastMsg = messagesWithContent[0]
      const snippet = lastMsg.content || lastMsg.think || ''
      return snippet.length > 70 ? snippet.substring(0, 70).trim() + '...' : snippet
    },
    toggleSearchMode() {
      this.isSearching = !this.isSearching
      this.showUserFilterDropdown = false
      if (!this.isSearching) {
        this.searchResultsData = null
      }
    },
    closeSearch() {
      this.isSearching = false
      this.searchResultsData = null
    },
    onSearchResults(searchData) {
      this.searchResultsData = searchData.results
    },
    onSearchError(error) {
      console.error('Search error:', error)
    },
    onNoResults() {
      this.searchResultsData = { results: [], total: 0 }
    },
    toggleUserFilterDropdown() {
      this.showUserFilterDropdown = !this.showUserFilterDropdown
    },
    selectUserFilter(user) {
      this.selectedUserId = user?.id
      this.showUserFilterDropdown = false
      this.limit = 10
    },
    clearUserFilter() {
      this.selectedUserId = null
      this.showUserFilterDropdown = false
      this.limit = 10
    },
    chatInvolvesUser(chat, userId) {
      if (!chat || !userId) return false

      // Check if user is in profiles array
      if (chat.profiles && Array.isArray(chat.profiles)) {
        if (chat.profiles.some(p => p?.id === userId || p?.user_id === userId)) {
          return true
        }
      }

      // Check if any message is from this user
      if (chat.messages && Array.isArray(chat.messages)) {
        if (chat.messages.some(m => m?.created_by === userId || m?.user_id === userId)) {
          return true
        }
      }

      // Check if user created the chat
      if (chat.created_by === userId) {
        return true
      }

      return false
    }
  }
}
</script>
